/**
 * Maximum OPE byte count. The Boldyreva scheme's hypergeometric sampling is O(range/2)
 * per recursion level, so the domain (256^bytes) must stay small enough for practical
 * encrypt/decrypt times. At 2 bytes (domain 65536, range 655360), each level does
 * ~300K AES operations — acceptable. At 3 bytes (domain 16M), each level would do
 * ~80M operations — too slow for synchronous use.
 */
private static final int MAX_OPE_BYTES = 2;

/**
 * Returns the byte count for OPE encoding of the given field type.
 * This determines how many bytes of the serialized value are used for OPE ordering.
 * Capped at {@link #MAX_OPE_BYTES} to keep OPE performance practical.
 *
 * <p>For types wider than MAX_OPE_BYTES (INT32, INT64, TIMESTAMP), only the
 * most-significant bytes participate in OPE ordering. Values that differ only
 * in their lower bytes may map to the same ciphertext order.
 */
private static int opeMaxBytes(FieldType type) {
    if (type instanceof FieldType.Primitive p) {
        return switch (p) {
            case INT8 -> 1;
            case INT16 -> Math.min(2, MAX_OPE_BYTES);
            case INT32 -> Math.min(4, MAX_OPE_BYTES);
            case INT64, TIMESTAMP -> Math.min(8, MAX_OPE_BYTES);
            default -> throw new IllegalArgumentException(
                    "OrderPreserving encryption is not supported for field type " + p);
        };
    } else if (type instanceof FieldType.BoundedString bs) {
        return Math.min(bs.maxLength(), MAX_OPE_BYTES);
    }
    throw new IllegalArgumentException(
            "OrderPreserving encryption is not supported for field type " + type);
}
